import shutil, openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

LIST_NAME = "LIST"
if LIST_NAME not in wb.sheetnames:
    wb.create_sheet(LIST_NAME)

ws_list = wb[LIST_NAME]

list_idx = None
for i, name in enumerate(wb.sheetnames):
    if name.strip().upper() == LIST_NAME.upper():
        list_idx = i
        break

if list_idx is None:
    source_names = [n for n in wb.sheetnames if n.strip().upper() != LIST_NAME.upper()]
else:
    source_names = wb.sheetnames[:list_idx]

def as_number(v):
    if isinstance(v, bool):
        return None
    if isinstance(v, (int, float)):
        return v
    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        if s.startswith("(") and s.endswith(")"):
            s = "-" + s[1:-1]
        if s.endswith("%"):
            try:
                return float(s[:-1]) / 100.0
            except ValueError:
                return None
        s = s.replace(",", "").replace("$", "").replace("€", "").replace("£", "")
        try:
            return float(s)
        except ValueError:
            return None
    return None

def clean(x):
    if isinstance(x, float) and x.is_integer():
        return int(x)
    return x

clear_max = max(5, len(source_names) + 2)
for row in ws_list.iter_rows(min_row=2, max_row=clear_max, min_col=1, max_col=5):
    for cell in row:
        cell.value = None

results = []
total_c = 0
total_d = 0

for name in source_names:
    if name not in vals.sheetnames:
        continue

    src = vals[name]
    c_sum = 0
    d_sum = 0
    max_row = src.max_row or 1

    for r in range(1, max_row + 1):
        cv = as_number(src.cell(row=r, column=3).value)
        dv = as_number(src.cell(row=r, column=4).value)
        if cv is not None:
            c_sum += cv
        if dv is not None:
            d_sum += dv

    c_sum = clean(c_sum)
    d_sum = clean(d_sum)
    e_sum = clean(c_sum - d_sum)

    results.append((name.strip(), c_sum, d_sum, e_sum))
    total_c += c_sum
    total_d += d_sum

for i, (name, c, d, e) in enumerate(results):
    r = 2 + i
    ws_list.cell(row=r, column=1, value=i + 1)
    ws_list.cell(row=r, column=2, value=name)
    ws_list.cell(row=r, column=3, value=c)
    ws_list.cell(row=r, column=4, value=d)
    ws_list.cell(row=r, column=5, value=e)

total_row = len(results) + 2
ws_list.cell(row=total_row, column=2, value="TOTAL")
ws_list.cell(row=total_row, column=3, value=clean(total_c))
ws_list.cell(row=total_row, column=4, value=clean(total_d))
ws_list.cell(row=total_row, column=5, value=clean(total_c - total_d))

print("source sheets:", source_names)
print("results:", results)
print("totals:", clean(total_c), clean(total_d), clean(total_c - total_d))

wb.save(OUT)
